public class TilePackager extends TileBlockEntityCyclic implements MenuProvider, WorldlyContainer {

  static enum Fields {
    TIMER, REDSTONE, BURNMAX;
  }

  static final int MAX = TileBattery.MENERGY * 10;
  public static ModConfigSpec.IntValue POWERCONF;
  public static ModConfigSpec.IntValue TIMERCONF;
  EnergyStorageWrapper energy = new EnergyStorageWrapper(MAX, MAX);
  ItemStackHandler inputSlots = new ItemStackHandler(1) {

    @Override
    public boolean isItemValid(int slot, ItemStack stack) {
      return isItemStackValid(stack);
    }
  };
  ItemStackHandler outputSlots = new ItemStackHandler(1);
  final ItemStackHandlerWrapper inventory = new ItemStackHandlerWrapper(inputSlots, outputSlots);

  public TilePackager(BlockPos pos, BlockState state) {
    super(TileRegistry.PACKAGER.get(), pos, state);
    this.needsRedstone = 0;
  }

  private boolean isItemStackValid(ItemStack stack) {
    if (level == null) {
      return false;
    }
    return UtilPackager.isItemStackValid(level.getRecipeManager(), level.registryAccess(), stack);
  }

  public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, TilePackager e) {
    e.tick();
  }

  public void tick() {
    this.syncEnergy();
    if (this.requiresRedstone() && !this.isPowered()) {
      setLitProperty(false);
      return;
    }
    ItemStack stack = inputSlots.getStackInSlot(0);
    if (stack.isEmpty()) {
      timer = TIMERCONF.get();
      setLitProperty(false);
      return;
    }
    if (POWERCONF.get() > 0 && energy.getEnergyStored() < POWERCONF.get()) {
      return;
    }
    setLitProperty(true);
    if (--timer > 0) {
      return;
    }
    timer = TIMERCONF.get();
    tryDoPackage();
  }

  private void tryDoPackage() {
    ItemStack stack = inputSlots.getStackInSlot(0);
    if (level == null) {
      return;
    }
    final CraftingRecipe recipe = UtilPackager.getRecipeForItemStack(level.getRecipeManager(), level.registryAccess(), stack);
    if (recipe == null) {
      return;
    }
    if (outputSlots.insertItem(0, recipe.getResultItem(level.registryAccess()).copy(), true).isEmpty()) {
      final int total = UtilPackager.getIngredientsInRecipe(recipe);
      final ItemStack output = recipe.getResultItem(level.registryAccess()).copy();
      inputSlots.extractItem(0, total, false);
      outputSlots.insertItem(0, output, false);
      energy.extractEnergy(POWERCONF.get(), false);
      this.updateComparatorOutputLevel();
    }
  }

  @Override
  public Component getDisplayName() {
    return BlockRegistry.PACKAGER.get().getName();
  }

  @Override
  public AbstractContainerMenu createMenu(int i, Inventory playerInventory, Player playerEntity) {
    return new ContainerPackager(i, level, worldPosition, playerInventory, playerEntity);
  }

  @Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    if (tag.contains(NBTENERGY)) {
      energy.deserializeNBT(registries, tag.get(NBTENERGY));
    }
    inventory.deserializeNBT(registries, tag.getCompound(NBTINV));
    super.loadAdditional(tag, registries);
  }

  @Override
  public void saveAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    tag.put(NBTENERGY, energy.serializeNBT(registries));
    tag.put(NBTINV, inventory.serializeNBT(registries));
    super.saveAdditional(tag, registries);
  }

  @Override
  public int getField(int id) {
    switch (Fields.values()[id]) {
      case REDSTONE:
        return this.needsRedstone;
      case TIMER:
        return this.timer;
      case BURNMAX:
        return TIMERCONF.get();
      default:
      break;
    }
    return 0;
  }

  @Override
  public void setField(int field, int value) {
    switch (Fields.values()[field]) {
      case REDSTONE:
        this.needsRedstone = value % 2;
      break;
      case TIMER:
        this.timer = value;
      break;
      case BURNMAX:
      break;
    }
  }

  @Override
  public IItemHandler getItemHandler(Direction side) {
    return inventory;
  }

  @Override
  public IEnergyStorage getEnergyHandler(Direction side) {
    return energy;
  }

  @Override
  public int[] getSlotsForFace(Direction direction) {
    return inventory.getSlotsForFace(direction);
  }

  @Override
  public boolean canPlaceItemThroughFace(int i, ItemStack itemStack, Direction direction) {
    return inventory.canPlaceItemThroughFace(i, itemStack, direction);
  }

  @Override
  public boolean canTakeItemThroughFace(int i, ItemStack itemStack, Direction direction) {
    return inventory.canTakeItemThroughFace(i, itemStack, direction);
  }
}

package com.lothrazar.cyclic.block.packager;

import java.util.HashMap;
import java.util.Map;
import net.minecraft.core.RegistryAccess;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.*;
import net.neoforged.neoforge.common.Tags;
//import net.neoforged.neoforge.common.Tags;

/**
 * https://github.com/Lothrazar/Cyclic/commit/2cd2376fd07685414b5a8a2a52250caab8143d9b#diff-f5ee2272c17948b8822c0020ec2b3f35b8dea7ec714d70a11355717c9d3a92f0
 * 
 * Packager PR @author https://github.com/Lothrazar/Cyclic/pull/2013
 *
 */
public class UtilPackager {

  private static final Map<Item, CraftingRecipe> fourItemRecipeCache = new HashMap<>();
  private static final Map<Item, CraftingRecipe> nineItemRecipeCache = new HashMap<>();
  private static final Map<CraftingRecipe, Integer> ingredientsInRecipeCache = new HashMap<>();
  private static final Map<Item, Boolean> itemValidCache = new HashMap<>();
  private static final Map<CraftingRecipe, Boolean> recipeValidCache = new HashMap<>();

  private UtilPackager() {}

  private static Map<Item, CraftingRecipe> getFourItemRecipeCache(final RecipeManager recipeManager, RegistryAccess ra) {
    if (fourItemRecipeCache.isEmpty()) {
      buildRecipeCaches(recipeManager, ra);
    }
    return fourItemRecipeCache;
  }

  public static int getIngredientsInRecipe(final CraftingRecipe recipe) {
    return ingredientsInRecipeCache.computeIfAbsent(recipe, k -> {
      int count = 0;
      for (final Ingredient ingredient : recipe.getIngredients()) {
        if (ingredient == Ingredient.EMPTY) {
          continue;
        }
        final ItemStack[] matchingStacks = ingredient.getItems();
        if (matchingStacks.length == 0) {
          continue;
        }
        count++;
      }
      return count;
    });
  }

  private static Map<Item, CraftingRecipe> getNineItemRecipeCache(final RecipeManager recipeManager, RegistryAccess ra) {
    if (nineItemRecipeCache.isEmpty()) {
      buildRecipeCaches(recipeManager, ra);
    }
    return nineItemRecipeCache;
  }

  public static CraftingRecipe getRecipeForItemStack(final RecipeManager recipeManager, RegistryAccess ra, final ItemStack itemStack) {
    if (itemStack.getCount() >= 9) {
      final CraftingRecipe recipe = getNineItemRecipeCache(recipeManager, ra).get(itemStack.getItem());
      if (recipe != null) {
        return recipe;
      }
    }
    if (itemStack.getCount() >= 4) {
      return getFourItemRecipeCache(recipeManager, ra).get(itemStack.getItem());
    }
    return null;
  }

  public static boolean isItemStackValid(final RecipeManager recipeManager, RegistryAccess ra, final ItemStack itemStack) {
    return UtilPackager.itemValidCache.computeIfAbsent(itemStack.getItem(), item -> getFourItemRecipeCache(recipeManager, ra).containsKey(item)
        || getNineItemRecipeCache(recipeManager, ra).containsKey(item));
  }

  public static boolean isRecipeValid(final CraftingRecipe recipe, RegistryAccess ra) {
    return recipeValidCache.computeIfAbsent(recipe, k -> {
      final ItemStack recipeOutput = recipe.getResultItem(ra);
      if (recipeOutput.getMaxStackSize() == 1 || recipeOutput.getCount() != 1) {
        return false;
      }
      Ingredient mainIngredient = null;
      ItemStack mainIngredientStack = null;
      int count = 0;
      for (final Ingredient ingredient : recipe.getIngredients()) {
        if (ingredient == Ingredient.EMPTY) {
          continue;
        }
        final ItemStack[] matchingStacks = ingredient.getItems(); //.getMatchingStacks();
        if (matchingStacks.length == 0) {
          continue;
        }
        final ItemStack matchingStack = matchingStacks[0];
        if (mainIngredient != null && !mainIngredient.test(matchingStack)) {
          return false;
        }
        mainIngredient = ingredient;
        mainIngredientStack = matchingStack;
        count++;
      }
      if (mainIngredient == null) {
        return false;
      }
      boolean outIsStorage = recipeOutput.is(Tags.Items.STORAGE_BLOCKS);
      boolean inIsIngot = mainIngredientStack.is(Tags.Items.INGOTS);
      if (!outIsStorage && inIsIngot) {
        return false;
      }
      return count == 4 || count == 9;
    });
  }

  public static void buildRecipeCaches(final RecipeManager recipeManager, RegistryAccess ra) {
    recipeLoop: for (final RecipeHolder<CraftingRecipe> r : recipeManager.getAllRecipesFor(RecipeType.CRAFTING)) {
      CraftingRecipe recipe = r.value();
      final ItemStack recipeOutput = recipe.getResultItem(ra);
      if (recipeOutput.getMaxStackSize() == 1 || recipeOutput.getCount() != 1) {
        continue;
      }
      Ingredient mainIngredient = null;
      ItemStack mainIngredientStack = null;
      int count = 0;
      for (final Ingredient ingredient : recipe.getIngredients()) {
        if (ingredient == Ingredient.EMPTY) {
          continue;
        }
        final ItemStack[] matchingStacks = ingredient.getItems();
        if (matchingStacks.length != 1) {
          recipeValidCache.put(recipe, false);
          continue recipeLoop;
        }
        final ItemStack matchingStack = matchingStacks[0];
        if (mainIngredient != null && !mainIngredient.test(matchingStack)) {
          recipeValidCache.put(recipe, false);
          continue recipeLoop;
        }
        mainIngredient = ingredient;
        mainIngredientStack = matchingStack;
        count++;
      }
      if (mainIngredient == null) {
        continue;
      }
      boolean outIsStorage = recipeOutput.is(Tags.Items.STORAGE_BLOCKS);
      final Item mainIngredientItem = mainIngredientStack.getItem();
      boolean inIsIngot = mainIngredientStack.is(Tags.Items.INGOTS);
      if (!outIsStorage && inIsIngot) {
        continue;
      }
      if (count == 4) {
        fourItemRecipeCache.put(mainIngredientItem, recipe);
        ingredientsInRecipeCache.put(recipe, 4);
        recipeValidCache.put(recipe, true);
      }
      else if (count == 9) {
        nineItemRecipeCache.put(mainIngredientItem, recipe);
        ingredientsInRecipeCache.put(recipe, 9);
        recipeValidCache.put(recipe, true);
      }
      else {
        recipeValidCache.put(recipe, false);
      }
    }
  }
}

package com.lothrazar.cyclic.item.boomerang;

import java.util.List;
import com.lothrazar.cyclic.ModCyclic;
import com.lothrazar.cyclic.config.ConfigRegistry;
import com.lothrazar.cyclic.item.boomerang.BoomerangItem.Boomer;
import com.lothrazar.cyclic.registry.PotionEffectRegistry;
import com.lothrazar.library.util.EntityUtil;
import com.lothrazar.library.util.ItemStackUtil;
import com.lothrazar.library.util.LevelWorldUtil;
import com.lothrazar.library.core.Const;
